const inp=input||{},ev=inp.event||{},action=String(ev.action||''),bindings=Array.isArray(templateBindings)?templateBindings:[];
const R=__ROLE_DEFINITIONS__;
const screens=[['overview','Overview'],['sites','Study sites'],['questionnaire','Questionnaires'],['comparison','Compare sites'],['pipeline','Selection'],['startup','Startup readiness']];
const defCols={studies:['name','protocol_code','phase','owner','status'],sites:['name','country','institution_type','specialty','verified_date'],investigators:['name','site_id','specialty','affiliation_date'],candidates:['site_id','stage','owner','decision_due'],criteria:['name','section','mandatory','weight','version'],responses:['name','criterion_id','answer','source_date','respondent_role'],evaluations:['name','candidate_id','status','reviewer','review_date'],startup:['name','candidate_id','item_type','planned_date','status']};
const esc=x=>String(x===null||x===undefined?'':x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
