 if(role==='candidates'){complete('candidates','sites','studies');if(all('candidates').rows.some(x=>x.id!==id&&x.data.study_id===d.study_id&&x.data.site_id===d.site_id))throw Error('This institution is already a candidate for the study');if(d.lead_investigator_id&&get('investigators',d.lead_investigator_id)?.data.site_id!==d.site_id)throw Error('Linked PI is not affiliated with the selected institution');}
