function startup(){
 let needed=['startup','candidates','sites','evaluations'],ok=hasCoverage(needed)&&!consistency().length,ss=scoped('startup',all('startup').rows),selected=scoped('candidates',all('candidates').rows).filter(c=>c.data.stage==='Selected');
 let due=ss.filter(x=>x.data.status!=='Completed'&&iso(x.data.planned_date)&&x.data.planned_date<st.asOf).sort((a,b)=>String(a.data.planned_date).localeCompare(String(b.data.planned_date)));
 let tiles=ok?selected.map(c=>{let tasks=ss.filter(x=>x.data.candidate_id===c.id);let done=tasks.filter(x=>x.data.status==='Completed').length;return'<div class="sf-activation-tile"><b>'+esc(label('sites',c.data.site_id))+'</b><small>'+esc(get('sites',c.data.site_id)?.data.country||'')+'</small><div class="sf-progress-line"><i style="width:'+(tasks.length?Math.round(100*done/tasks.length):0)+'%"></i></div><span>'+done+' / '+tasks.length+' milestones recorded complete</span>'+btn('View selected site','detail:candidates:'+c.id,'sf-secondary')+'</div>'}).join(''):'<p class="sf-empty">Startup cannot be verified without current authorized records.</p>';
 return heading('Startup readiness','Track documented handoff milestones after explicit sponsor selection',cutoff())+warning(needed)+'<div class="sf-stat-grid three">'+stat('Selected sites',ok?selected.length:'—','Explicit sponsor selections',true)+stat('Open startup items',ok?ss.filter(x=>x.data.status!=='Completed').length:'—','Not auto-verified')+stat('Overdue blockers',ok?due.length:'—','Due before selected cutoff')+'</div>'+
 '<section class="sf-card">'+cardTitle('Activation by selected site','<span class="sf-muted">Planning metadata · no automatic site greenlight</span>')+(!ok?'<p class="sf-empty">Selected-site coverage unavailable.</p>':selected.length?'<div class="sf-activation-grid">'+tiles+'</div>':'<p class="sf-empty">No selected sites in this study yet.</p>')+'</section>'+
 '<section class="sf-card">'+cardTitle('Upcoming milestones and blockers','<span class="sf-muted">Target vs. actual dates, owners and action</span>')+(ok?'<div class="sf-schedule">'+ss.filter(x=>x.data.status!=='Completed').sort((a,b)=>String(a.data.planned_date||'9999').localeCompare(String(b.data.planned_date||'9999'))).slice(0,6).map(x=>{let d=x.data;return'<div class="sf-schedule-row"><div><b>'+esc(d.name)+'</b><small>'+esc(label('sites',get('candidates',d.candidate_id)?.data.site_id))+'</small></div><div>'+tag(d.status)+'</div><div><small>Target</small><b>'+esc(d.planned_date||'—')+'</b></div><div><small>Actual</small><b>'+esc(d.actual_date||'—')+'</b></div>'+btn('Details','detail:startup:'+x.id,'sf-row-link')+'</div>'}).join('')+'</div>':'<p class="sf-empty">Readiness unavailable.</p>')+'</section>'+
 '<section class="sf-card">'+cardTitle('All startup milestones','<span class="sf-muted">Paginated approved register</span>')+register('startup')+'</section><p class="sf-disclaimer">Completed items are administrative metadata; they are not ethics approval, eTMF validation, greenlight or permission to enroll participants.</p>';
}
function editorField(role,f,d){if(f.key==='archived')return '';let value=d[f.key]??'',options=f.kind.startsWith('relation-')?all(f.kind.slice(9)).rows.map(row=>[row.id,row.data.name]):f.kind==='select'?f.options.map(x=>[x,x]):null;
 let locked=!can(role,[f.key])||(role==='evaluations'&&['evidence_snapshot','weighted_score'].includes(f.key));let attrs=(locked?' disabled ':'')+' name="'+esc(f.key)+'" data-ui-state="true" data-action="field:'+esc(f.key)+'" '+(f.required?'required ':'')+'aria-label="'+esc(f.label)+'" ';
 let control=options?'<select '+attrs+'><option value="">Choose…</option>'+options.map(([id,txt])=>'<option value="'+esc(id)+'" '+(String(id)===String(value)?'selected':'')+'>'+esc(txt)+'</option>').join('')+'</select>':f.kind==='longtext'?'<textarea rows="3" '+attrs+'>'+esc(value)+'</textarea>':f.kind==='boolean'?'<select '+attrs+'><option value="true" '+(bool(value)?'selected':'')+'>Yes</option><option value="false" '+(!bool(value)?'selected':'')+'>No</option></select>':'<input type="'+(f.kind==='date'?'date':['number','money'].includes(f.kind)?'number':'text')+'" '+(['number','money'].includes(f.kind)?'step="any" ':'')+attrs+'value="'+esc(value)+'" />';
 return '<label class="sf-field '+(f.kind==='longtext'?'wide':'')+'"><span>'+esc(f.label)+(f.required?' *':'')+(locked?' (read only)':'')+'</span>'+control+'</label>';}
function editorModal(){let ed=st.editor;if(!ed)return '';return '<div class="sf-overlay"><div class="sf-drawer" role="dialog" aria-modal="true" aria-label="'+(ed.mode==='edit'?'Edit ':'Add ')+esc(ed.role)+'"><div class="sf-drawer-head"><div><h2>'+(ed.mode==='edit'?'Edit ':'Add ')+esc(ed.role.replace(/s$/,''))+'</h2><p>All required fields remain available regardless of layout. Changes require platform review.</p></div>'+btn(icon('close',18),'ignore','sf-secondary',false,'aria-label="Close editor"')+'</div><form data-action="save-form"><div class="sf-drawer-body">'+R[ed.role].map(f=>editorField(ed.role,f,ed.draft)).join('')+'</div><div class="sf-drawer-foot">'+btn('Ignore','ignore','sf-secondary')+'<button class="sf-btn sf-primary" type="submit">Review changes</button></div></form></div></div>';}
function archiveModal(){let d=st.del;if(!d)return '';return '<div class="sf-overlay"><div class="sf-confirm" role="alertdialog" aria-label="Archive record"><h2>Archive '+esc(d.name)+'?</h2><p>Archiving is a versioned, reviewed update. All active linked records must be reassigned or archived before a parent can be archived. Historical evidence remains retained.</p><div>'+btn('Cancel','cancel-archive','sf-secondary')+btn('Review archive','review-archive','sf-primary')+'</div></div></div>';}
function detailModal(){let d=st.detail;if(!d)return '';let row=get(d.role,d.id);if(!row)return '';let extra=d.role==='sites'?'<div class="sf-drawer-links">'+btn('Add professional PI','prefill:investigators:site_id:'+row.id,'sf-secondary',!can('investigators'))+'</div>':d.role==='candidates'?'<div class="sf-evidence-brief">'+((e)=>'<b>Questionnaire evidence</b><span>'+(e.complete?(e.mandatory?'Complete mandatory assessment · '+e.percent+'%':'Mandatory checks unresolved'):esc(e.reason||'Incomplete'))+'</span>')(snapshot(row))+'</div><div class="sf-drawer-links">'+btn('Record questionnaire response','prefill:responses:candidate_id:'+row.id,'sf-secondary',!can('responses'))+btn('Add assessment','prefill:evaluations:candidate_id:'+row.id,'sf-secondary',!can('evaluations'))+'</div>':'';return '<div class="sf-overlay"><div class="sf-drawer" role="dialog" aria-modal="true" aria-label="Record details"><div class="sf-drawer-head"><div><h2>'+esc(row.data.name)+'</h2><p>Version '+row.version+' · authorized business record</p></div>'+btn(icon('close',18),'close-detail','sf-secondary',false,'aria-label="Close details"')+'</div><div class="sf-detail-list">'+R[d.role].filter(f=>f.key!=='archived').map(f=>'<div><span>'+esc(f.label)+'</span><strong>'+esc(format(d.role,f.key,row.data[f.key]))+'</strong></div>').join('')+extra+'</div><div class="sf-drawer-foot">'+btn('Close','close-detail','sf-secondary')+btn('Edit','edit:'+d.role+':'+row.id,'sf-primary',!can(d.role))+'</div></div></div>';}
const views={overview,sites:directory,questionnaire,comparison,pipeline,startup};
const html='<div class="sf-shell"><aside class="sf-sidebar"><div class="sf-app-title"><strong>'+esc(layout.heading||cfg.heading||'Site Feasibility')+'</strong><small>Sponsor clinical operations</small></div><nav aria-label="App sections">'+ordered.map(id=>{let s=screens.find(x=>x[0]===id);return btn(icon(id)+'<span>'+esc(s[1])+'</span>','nav:'+id,'sf-nav '+(id===st.route?'active':''),false,'aria-current="'+(id===st.route?'page':'false')+'" aria-label="Open '+esc(s[1])+'"');}).join('')+'</nav><div class="sf-sidebar-foot"><i></i> Internal workspace<small>Permissions via TrialAgents</small></div></aside><main class="sf-main"><div class="sf-topbar"><div class="sf-study-context"><span>STUDY</span>'+selectorStudy()+'</div><div><span class="sf-top-pill">Internal workspace</span>'+btn(icon('settings',18),'tracker:layout','sf-settings',false,'aria-label="Layout settings"')+'</div></div><div class="sf-content">'+(st.notice?'<div class="sf-notice" role="status">'+esc(st.notice)+btn('Dismiss','clear-notice','sf-notice-close')+'</div>':'')+(views[st.route]||overview)()+'</div><footer class="sf-footer">Institution-level feasibility only · reviewed writes · no patient-level data</footer></main></div>'+editorModal()+archiveModal()+detailModal();
